import base64, json
def b64u(d):
    return base64.urlsafe_b64encode(json.dumps(d).encode()).rstrip(b"=").decode()
tok = b64u({"alg": "EdDSA"}) + "." + b64u({"sub": "alice", "role": "user"}) + ".c2ln"
p = tok.split(".")[1]
print(json.loads(base64.urlsafe_b64decode(p + "=" * (-len(p) % 4)))["role"])

import jwt

def verify(token, key):
    alg = jwt.get_unverified_header(token)["alg"]
    return jwt.decode(token, key, algorithms=[alg], audience="orders-api")

def expired(now, exp, leeway=30):
    return now > exp + leeway

print(expired(1_000_050, 1_000_000), expired(1_000_020, 1_000_000))
